import React from "react";

type ButtonVariant =
  | "primary"
  | "accent"
  | "outline"
  | "subtle"
  | "secondary"
  | "danger";

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: ButtonVariant;
  children: React.ReactNode;
}

export function Button({
  variant = "primary",
  children,
  className = "",
  ...props
}: ButtonProps) {
  const baseStyle =
    "font-inter text-[15px] font-medium py-2 px-6 rounded-full transition-all duration-200 cursor-pointer inline-flex items-center justify-center border";

  const variants: Record<ButtonVariant, string> = {
    primary:
      "bg-green-primary text-text border-transparent hover:brightness-110",
    accent:
      "bg-gold-accent text-bg border-transparent font-semibold hover:brightness-110",
    outline: "bg-transparent text-text border-border hover:bg-raised",
    subtle: "bg-green-deep text-text border-transparent hover:brightness-125",
    secondary: "bg-raised text-text border-transparent hover:brightness-125",
    danger: "bg-transparent text-danger border-danger hover:bg-danger/10",
  };

  return (
    <button
      className={`${baseStyle} ${variants[variant]} ${className}`}
      {...props}
    >
      {children}
    </button>
  );
}
